create table if not exists public.document_analysis_results (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.documents(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, result jsonb not null, source text not null default 'ai' check (source in ('ai','demo')), created_at timestamptz not null default now()); create table if not exists public.document_reviews (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.documents(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, facts jsonb not null, confirmed_at timestamptz not null default now(), created_at timestamptz not null default now()); create index if not exists document_analysis_results_document_id_idx on public.document_analysis_results(document_id, created_at desc); create index if not exists document_analysis_results_user_id_idx on public.document_analysis_results(user_id, created_at desc); create index if not exists document_reviews_document_id_idx on public.document_reviews(document_id, created_at desc); create index if not exists document_reviews_user_id_idx on public.document_reviews(user_id, created_at desc); alter table public.document_analysis_results enable row level security; alter table public.document_reviews enable row level security; do $$ begin if not exists (select 1 from pg_policies where schemaname='public' and tablename='document_analysis_results' and policyname='document_analysis_owner') then create policy document_analysis_owner on public.document_analysis_results for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); end if; if not exists (select 1 from pg_policies where schemaname='public' and tablename='document_reviews' and policyname='document_reviews_owner') then create policy document_reviews_owner on public.document_reviews for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); end if; end $$
